import{_ as a,o as t,c as l,ag as i}from"./chunks/framework.B9unkguw.js";const y=JSON.parse('{"title":"Plan View - Rally Points","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/plan_view/plan_rally_points.md","filePath":"en/qgc-user-guide/plan_view/plan_rally_points.md"}'),n={name:"en/qgc-user-guide/plan_view/plan_rally_points.md"};function o(r,e,s,p,h,d){return t(),l("div",null,e[0]||(e[0]=[i('<h1 id="plan-view-rally-points" tabindex="-1">Plan View - Rally Points <a class="header-anchor" href="#plan-view-rally-points" aria-label="Permalink to &quot;Plan View - Rally Points&quot;">​</a></h1><p>Rally Points are alternative landing or loiter locations. They are typically used to provide a safer or more convenient (e.g. closer) destination than the home position in Return/RTL mode.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><em>QGroundControl</em> will not display the Rally Point options if they are not supported by the connected vehicle firmware.</p></div><h2 id="rally-point-usage" tabindex="-1">Rally Point Usage <a class="header-anchor" href="#rally-point-usage" aria-label="Permalink to &quot;Rally Point Usage&quot;">​</a></h2><p>To create Rally Points:</p><ol><li>Navigate to the Plan View</li><li>Select the <strong>Rally Points</strong> layer using the <a href="./plan_view.html#layer_switcher">Layer Switcher</a> in the top-right area of the map (or expand the <strong>Rally Points</strong> section in the <a href="./plan_view.html#plan_editor_panel">Plan Editor Panel</a>)</li><li>Click the map wherever you want rally points. <ul><li>An <strong>R</strong> marker is added for each</li><li>The currently active marker has a different color (green) and its editor is expanded in the <em>Rally Points</em> section.</li></ul></li><li>Make any rally point active by selecting it on the map or in the <em>Rally Points</em> section: <ul><li>Move the active rally point by either dragging it on the map or editing the position fields in its editor.</li><li>Delete a rally point by pressing the <strong>X</strong> delete button on its editor.</li></ul></li></ol><h2 id="upload-rally-points" tabindex="-1">Upload Rally Points <a class="header-anchor" href="#upload-rally-points" aria-label="Permalink to &quot;Upload Rally Points&quot;">​</a></h2><p>Rally points are uploaded along with the rest of the plan using the <strong>Upload</strong> button in the <a href="./plan_view.html#file">Plan Toolbar</a>.</p>',8)]))}const u=a(n,[["render",o]]);export{y as __pageData,u as default};
